<?php
$this->layout('layouts/studio');
$levelLabels=['debug'=>'Debug','info'=>'Informação','notice'=>'Aviso','warning'=>'Atenção','error'=>'Erro','critical'=>'Crítico','alert'=>'Alerta','emergency'=>'Emergência'];
$statusLabels=['open'=>'Aberto','resolved'=>'Resolvido','ignored'=>'Ignorado'];
$hasFilters=$filters['search']!==''||$filters['level']!==''||$filters['status']!==''||$filters['channel']!==''||$filters['period']!=='30'||!empty($_GET['date_from'])||!empty($_GET['date_to'])||$filters['sort']!=='newest'||$filters['perPage']!==30;
$pageUrl=static fn(int $number)=>url($adminBase . '/system-logs/p/'.$number).($queryString?'?'.$queryString:'');
?>
<script>document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('.studio-log-item').forEach(item=>{const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.name='log_ids[]';checkbox.value=(item.querySelector('form')?.action.match(/\/(\d+)$/)||[])[1]||'';checkbox.setAttribute('form','studio-log-bulk');checkbox.setAttribute('aria-label','Selecionar incidente');checkbox.addEventListener('click',event=>event.stopPropagation());item.querySelector('summary')?.prepend(checkbox)});document.querySelector('[data-log-select-all]')?.addEventListener('change',event=>document.querySelectorAll('[name="log_ids[]"]').forEach(input=>input.checked=event.target.checked));document.getElementById('studio-log-bulk')?.addEventListener('submit',event=>{if(!document.querySelector('[name="log_ids[]"]:checked')){event.preventDefault();window.StudioFeedback?.show('Selecione ao menos um incidente.','warning')}})})</script>
<script>document.addEventListener('click',event=>{const button=event.target.closest('.studio-log-details button[name="action"]');if(!button)return;let hidden=button.form.querySelector('input[type="hidden"][name="action"]');if(!hidden){hidden=document.createElement('input');hidden.type='hidden';hidden.name='action';button.form.append(hidden)}hidden.value=button.value})</script>
<section class="studio-page-header"><div><p class="studio-eyebrow">Sistema</p><h1 class="studio-page-title">Logs do sistema</h1><p class="studio-page-description">Acompanhe incidentes técnicos, falhas e eventos registrados pelo sistema.</p></div><div class="studio-page-actions"><button class="studio-btn" type="button" data-log-filter-open><ion-icon name="filter-outline"></ion-icon>Filtrar<?php if($hasFilters):?><span class="studio-filter-active-dot"></span><?php endif;?></button><span class="studio-counter"><?= number_format($total,0,',','.') ?> registro(s)</span></div></section>
<section class="studio-stats studio-log-stats"><article><i title="Total"><ion-icon name="document-text-outline"></ion-icon></i><div><span>Total</span><strong><?= number_format((int)($summary->total??0),0,',','.') ?></strong><small>Registros preservados</small></div></article><article><i title="Em aberto"><ion-icon name="alert-circle-outline"></ion-icon></i><div><span>Em aberto</span><strong><?= number_format((int)($summary->opened??0),0,',','.') ?></strong><small>Aguardando análise</small></div></article><article><i title="Críticos"><ion-icon name="warning-outline"></ion-icon></i><div><span>Críticos</span><strong><?= number_format((int)($summary->criticals??0),0,',','.') ?></strong><small>Erros prioritários</small></div></article><article><i title="Últimas 24h"><ion-icon name="time-outline"></ion-icon></i><div><span>Últimas 24h</span><strong><?= number_format((int)($summary->today??0),0,',','.') ?></strong><small>Atividade recente</small></div></article></section>
<section class="studio-panel studio-log-panel"><header class="studio-list-toolbar"><div><strong>Incidentes encontrados</strong><small><?= number_format($total,0,',','.') ?> resultado(s) · <?= $filters['perPage'] ?> por página</small></div><form id="studio-log-bulk" class="studio-actions" action="<?= url($adminBase . '/system-logs/action/0') ?>" method="post"><?= csrf_input() ?><label class="studio-check"><input type="checkbox" data-log-select-all> Todos</label><select class="studio-select" name="action" required><option value="">Ação em lote</option><option value="resolve">Resolver</option><option value="reopen">Reabrir</option><option value="ignore">Ignorar</option><option value="delete">Excluir tratados</option></select><button class="studio-btn" type="submit">Aplicar</button><?php if($hasFilters):?><a class="studio-btn" href="<?= url($adminBase . '/system-logs') ?>"><ion-icon name="close-outline"></ion-icon>Limpar filtros</a><?php endif;?></form></header>
<?php if(!$logs):?><div class="studio-empty">Nenhum registro corresponde aos filtros.</div><?php endif;?><div class="studio-log-list"><?php foreach($logs as $log):?><?php $context=json_decode((string)$log->context_json,true)?:[];?><details class="studio-log-item <?= htmlspecialchars($log->level) ?>"><summary><span class="studio-log-level"><?= htmlspecialchars($levelLabels[$log->level]??ucfirst($log->level)) ?></span><span class="studio-log-summary"><strong><?= htmlspecialchars($log->msg) ?></strong><small><code><?= htmlspecialchars($log->incident_id?:'LEG-'.$log->id) ?></code> · <?= htmlspecialchars($log->channel) ?> · <?= date_fmt($log->last_seen_at?:$log->created_at) ?><?= (int)$log->occurrences>1?' · '.(int)$log->occurrences.' ocorrências':'' ?></small></span><span class="studio-log-status <?= htmlspecialchars($log->status) ?>"><?= htmlspecialchars($statusLabels[$log->status]??$log->status) ?></span><ion-icon name="chevron-down-outline"></ion-icon></summary><div class="studio-log-details"><dl><div><dt>Código</dt><dd><?= htmlspecialchars((string)$log->code)?:'—' ?></dd></div><div><dt>Tipo</dt><dd><?= htmlspecialchars((string)$log->event_type)?:'—' ?></dd></div><div><dt>Usuário</dt><dd><?= htmlspecialchars(trim((string)$log->user_name))?:'Visitante/Sistema' ?></dd></div><div><dt>URL</dt><dd><?= htmlspecialchars((string)$log->url)?:'—' ?></dd></div><div><dt>IP</dt><dd><?= htmlspecialchars((string)$log->ip)?:'—' ?></dd></div><div><dt>Arquivo</dt><dd><code><?= htmlspecialchars((string)$log->file) ?><?= $log->line?':'.(int)$log->line:'' ?></code></dd></div></dl><?php if($context):?><h3>Contexto seguro</h3><pre><?= htmlspecialchars(json_encode($context,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)) ?></pre><?php endif;?><?php if($log->trace):?><h3>Rastreamento</h3><pre><?= htmlspecialchars($log->trace) ?></pre><?php endif;?><footer><form action="<?= url($adminBase . '/system-logs/action/'.$log->id) ?>" method="post"><?= csrf_input() ?><?php if($log->status==='open'):?><button class="studio-btn primary" name="action" value="resolve">Marcar resolvido</button><button class="studio-btn" name="action" value="ignore">Ignorar</button><?php else:?><button class="studio-btn" name="action" value="reopen">Reabrir incidente</button><?php endif;?></form></footer></div></details><?php endforeach;?></div>
<?php if($pages>1):?><footer class="studio-media-pagination"><span>Página <?= $page ?> de <?= $pages ?></span><nav class="studio-pagination"><?php if($page>1):?><a class="studio-pagination_item wide" href="<?= $pageUrl(1) ?>"><ion-icon name="play-skip-back-outline"></ion-icon><span>Primeira</span></a><a class="studio-pagination_item wide" href="<?= $pageUrl($page-1) ?>"><ion-icon name="chevron-back-outline"></ion-icon><span>Anterior</span></a><?php endif;?><?php for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++):?><a class="studio-pagination_item <?= $i===$page?'studio-pagination_active':'' ?>" href="<?= $pageUrl($i) ?>"><?= $i ?></a><?php endfor;?><?php if($page<$pages):?><a class="studio-pagination_item wide" href="<?= $pageUrl($page+1) ?>"><span>Próxima</span><ion-icon name="chevron-forward-outline"></ion-icon></a><a class="studio-pagination_item wide" href="<?= $pageUrl($pages) ?>"><span>Última</span><ion-icon name="play-skip-forward-outline"></ion-icon></a><?php endif;?></nav></footer><?php endif;?></section>
<div class="studio-filter-drawer" data-log-filter-drawer aria-hidden="true"><button class="studio-filter-backdrop" type="button" data-log-filter-close aria-label="Fechar filtros"></button><aside class="studio-filter-sheet" role="dialog" aria-modal="true" aria-labelledby="log-filter-title"><header><div><small>FILTROS DO LOG</small><h2 id="log-filter-title">Localizar incidentes</h2><p>Combine estado, gravidade, origem e período.</p></div><button type="button" data-log-filter-close aria-label="Fechar"><ion-icon name="close-outline"></ion-icon></button></header><form class="studio-pill-filter studio-pill-filter-drawer ajax_off" method="get" action="<?= url($adminBase . '/system-logs') ?>"><label class="studio-filter-search">Pesquisar<input name="q" value="<?= htmlspecialchars($filters['search']) ?>" placeholder="Incidente, mensagem, código ou URL"></label><fieldset><legend>Estado</legend><div><?php foreach([''=>'Todos','open'=>'Abertos','resolved'=>'Resolvidos','ignored'=>'Ignorados'] as $value=>$label):?><label><input type="radio" name="status" value="<?= $value ?>" <?= $filters['status']===$value?'checked':'' ?>><span><?= $label ?></span></label><?php endforeach;?></div></fieldset><fieldset><legend>Nível</legend><div><label><input type="radio" name="level" value="" <?= $filters['level']===''?'checked':'' ?>><span>Todos</span></label><?php foreach($levelLabels as $value=>$label):?><label><input type="radio" name="level" value="<?= $value ?>" <?= $filters['level']===$value?'checked':'' ?>><span><?= $label ?></span></label><?php endforeach;?></div></fieldset><fieldset><legend>Origem</legend><select name="channel"><option value="">Todas</option><?php foreach($channels as $item):?><option value="<?= htmlspecialchars($item->channel) ?>" <?= $filters['channel']===$item->channel?'selected':'' ?>><?= htmlspecialchars($item->channel) ?></option><?php endforeach;?></select></fieldset><fieldset><legend>Período rápido</legend><div><?php foreach(['today'=>'Hoje','7'=>'7 dias','30'=>'30 dias','90'=>'90 dias','all'=>'Todo o período'] as $value=>$label):?><label><input type="radio" name="period" value="<?= $value ?>" <?= $filters['period']===$value?'checked':'' ?>><span><?= $label ?></span></label><?php endforeach;?></div></fieldset><fieldset class="studio-custom-period"><legend>Período específico</legend><p>As datas substituem o período rápido.</p><div class="studio-date-range"><label>Data inicial<input type="date" name="date_from" value="<?= htmlspecialchars((string)($_GET['date_from']??'')) ?>"></label><i>até</i><label>Data final<input type="date" name="date_to" value="<?= htmlspecialchars((string)($_GET['date_to']??'')) ?>"></label></div></fieldset><fieldset><legend>Ordenação</legend><div><?php foreach(['newest'=>'Mais recentes','oldest'=>'Mais antigos','occurrences'=>'Mais recorrentes'] as $value=>$label):?><label><input type="radio" name="sort" value="<?= $value ?>" <?= $filters['sort']===$value?'checked':'' ?>><span><?= $label ?></span></label><?php endforeach;?></div></fieldset><fieldset><legend>Por página</legend><div><?php foreach([15,30,60,100] as $value):?><label><input type="radio" name="per_page" value="<?= $value ?>" <?= $filters['perPage']===$value?'checked':'' ?>><span><?= $value ?></span></label><?php endforeach;?></div></fieldset><footer><a class="studio-btn" href="<?= url($adminBase . '/system-logs') ?>">Limpar</a><button class="studio-btn primary" type="submit"><ion-icon name="filter-outline"></ion-icon>Aplicar filtros</button></footer></form></aside></div>
<?php $this->start('scripts')?><script>const logFilterDrawer=document.querySelector('[data-log-filter-drawer]');const toggleLogFilter=open=>{logFilterDrawer?.classList.toggle('open',open);logFilterDrawer?.setAttribute('aria-hidden',open?'false':'true');document.body.classList.toggle('studio-filter-open',open)};document.querySelector('[data-log-filter-open]')?.addEventListener('click',()=>toggleLogFilter(true));logFilterDrawer?.querySelectorAll('[data-log-filter-close]').forEach(button=>button.addEventListener('click',()=>toggleLogFilter(false)));logFilterDrawer?.querySelectorAll('input[type="date"]').forEach(input=>input.addEventListener('click',()=>typeof input.showPicker==='function'&&input.showPicker()));</script><?php $this->stop()?>
